//! Integration checks for the 3.5 navigation, shared controls and widget scenes.
use crate::{model::{Model,Action,Page},views::{self,ViewState},gpu::Gpu,draw::Text};
use dotisle_domain::desktop_widgets::{Kind,Size};
pub fn run(out:&std::path::Path,text:&mut Text,gpu:&mut Gpu)->Result<Vec<String>,String>{
 crate::shell::verify_overview_inputs(&out.join("deck-inputs"))?;
 let mut m=Model::new(out.join("widgets-model"),true);m.prefs.control_center_theme="Original".into();let mut captures=vec![];
 if Page::ALL.contains(&Page::Island)||Page::ALL.contains(&Page::Music){return Err("legacy settings/music destination leaked into navigation".into())}
 m.mode=2;m.dispatch(Action::QuickFocus);if m.timers.items.len()!=1||m.timers.items[0].mode!="pomodoro"{return Err("overview quick focus inherited stopwatch mode".into())}let id=m.timers.items[0].id.clone();let revision=m.timer_action_value(&id,"pause").ok_or("focus command missing")?["revision"].clone();if revision.is_null(){return Err("widget timer command lacks revision".into())}m.dispatch(Action::Timer(id,"pause"));if m.timers.items[0].running{return Err("overview focus did not pause".into())}
 for kind in Kind::ALL{m.dispatch(Action::WidgetAdd(kind,kind.default_size()));}if m.desktop_widgets.items.len()!=6{return Err("six widget commands did not add cards".into())}
 for dark in [false,true]{m.prefs.dark=dark;for kind in Kind::ALL{for size in Size::ALL{let view=crate::desktop_cards::render(&m,text,kind,size,"capture",(-1.,-1.),true,0.);let(w,h)=size.dimensions();if view.hits.iter().any(|h|h.rect.x0<0.||h.rect.x1>w||h.rect.y1>h64(size)){return Err("widget hit outside window".into())}let name=format!("widget-{kind:?}-{size:?}-{dark}.png");gpu.capture(&view.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}}}
 m.toast=None;m.prefs.dark=false;for(w,h)in [(1200.,800.),(900.,680.)]{for page in [Page::Home,Page::Widgets,Page::Notifications,Page::Settings]{m.page=page;m.scroll=0.;m.settings_tab=255;let state=ViewState{rail_y:112.+Page::ALL.iter().position(|p|*p==page).unwrap()as f64*82.,..Default::default()};let first=views::render(&m,text,w,h,&state);let nav=first.hits.iter().filter(|hit|matches!(hit.action,Action::Navigate(_))&&hit.rect.y0>h-110.).count();if nav<6{return Err("capsule dock omitted destinations".into())}for scroll in [0.,first.max_scroll]{m.scroll=scroll;let view=views::render(&m,text,w,h,&state);if view.hits.iter().any(|hit|hit.rect.y1>h||hit.rect.x1>w){return Err("3.5 view hit outside window".into())}let name=format!("350-{page:?}-{}-{}.png",w as u32,scroll as u32);gpu.capture(&view.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}}}

 m.prefs.control_center_theme="Original".into();m.toast=None;
 for dark in [false,true]{m.prefs.dark=dark;for(w,h)in [(1200.,800.),(900.,680.)]{m.page=Page::Home;for i in 0..5{m.scroll=i as f64*crate::overview::STEP;let v=views::render(&m,text,w,h,&ViewState::default());if v.max_scroll!=0.{return Err("infinite deck gained a finite document extent".into())}let relevant=v.hits.iter().filter(|hit|match i{0=>matches!(hit.action,Action::Media(_)|Action::Seek|Action::LayoutOpen),1=>matches!(hit.action,Action::Timer(..)|Action::QuickFocus),2=>matches!(hit.action,Action::EditTodo(_)),3=>matches!(hit.action,Action::Navigate(Page::Notifications)),_=>matches!(hit.action,Action::WidgetAdd(..))}).count();if relevant==0{return Err(format!("deck card {i} lost its inline actions"))}let name=format!("deck-{i}-{w:.0}-{dark}.png");gpu.capture(&v.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}
 m.scroll=crate::overview::STEP*0.45;let v=views::render(&m,text,w,h,&ViewState{scroll_blur:0.65,..Default::default()});let name=format!("deck-rolling-{w:.0}-{dark}.png");gpu.capture(&v.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}}
 m.page=Page::Home;m.prefs.control_center_theme="Original".into();m.prefs.dark=false;
 for position in [-crate::overview::STEP,0.,crate::overview::ring::CYCLE,crate::overview::ring::CYCLE*100.+crate::overview::STEP*4.]{
  m.scroll=position;let v=views::render(&m,text,900.,680.,&ViewState::default());let active=crate::overview::ring::index(position);let relevant=v.hits.iter().any(|hit|match active{0=>matches!(hit.action,Action::Seek),4=>matches!(hit.action,Action::WidgetAdd(..)),_=>false});if !relevant{return Err("looped card lost its live controls".into())}
  let mut wrapped=m.scroll;wrapped+=crate::overview::ring::CYCLE; m.scroll=wrapped;let next=views::render(&m,text,900.,680.,&ViewState::default());if v.hits.len()!=next.hits.len()||v.hits.iter().zip(&next.hits).any(|(a,b)|a.label!=b.label||a.rect!=b.rect){return Err("loop seam changed card hit geometry".into())}
 }
 for (label,position) in [("before",crate::overview::ring::CYCLE-crate::overview::STEP*0.25),("seam",crate::overview::ring::CYCLE),("after",crate::overview::ring::CYCLE+crate::overview::STEP*0.25),("reverse",-crate::overview::STEP*0.25)]{
  m.scroll=position;let v=views::render(&m,text,1200.,800.,&ViewState{scroll_blur:0.25,..Default::default()});let name=format!("deck-loop-{label}.png");gpu.capture(&v.scene,1200,800,&out.join(&name))?;captures.push(name);
 }
 if std::env::var_os("DOTISLE_CAPTURE_DECK_MOTION").is_some(){
  let frames=out.join("motion");std::fs::create_dir_all(&frames).map_err(|e|e.to_string())?;
  for frame in 0..96{let t=frame as f64/32.;let whole=t.floor();let f=((t-whole-0.25)/0.6).clamp(0.,1.);let eased=f*f*(3.-2.*f);m.scroll=(4.+whole+eased)*crate::overview::STEP;let v=views::render(&m,text,900.,680.,&ViewState{scroll_blur:if f>0.&&f<1.{0.45}else{0.},..Default::default()});gpu.capture(&v.scene,900,680,&frames.join(format!("{frame:03}.png")))?;}
 }
 m.dispatch(Action::LayoutOpen);let baseline=m.layout_editor.as_ref().unwrap().draft.clone();m.dispatch(Action::LayoutMove(0,1));if m.setting("MusicCustomLayout").is_object(){return Err("draft leaked into saved settings".into())}m.dispatch(Action::LayoutDiscard);if m.layout_editor.as_ref().unwrap().draft!=baseline{return Err("discard failed to restore the baseline".into())}m.dispatch(Action::LayoutToggle(2));m.dispatch(Action::LayoutStyle(1,"Segmented".into()));m.dispatch(Action::LayoutApply);let applied=lyric_core::custom_layout::Layout::from_value(&m.setting("MusicCustomLayout"))?;if !applied.thumb_enabled||applied.bar_style!="Segmented"{return Err("atomic layout apply dropped style settings".into())}
 for theme in ["Original","Nothing","Gallery","Nocturne"]{m.prefs.control_center_theme=theme.into();for dark in [false,true]{m.prefs.dark=dark;for(w,h)in [(1200.,800.),(900.,680.)]{for tab in 0..3{m.dispatch(Action::LayoutTab(tab));m.toast=None;let first=views::render(&m,text,w,h,&ViewState::default());for scroll in [0.,first.max_scroll]{m.scroll=scroll;let v=views::render(&m,text,w,h,&ViewState::default());if !v.hits.iter().any(|hit|matches!(hit.action,Action::LayoutApply)){return Err("editor apply button left the viewport".into())}let name=format!("layout-{theme}-{tab}-{w:.0}-{dark}-{scroll:.0}.png");gpu.capture(&v.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}}}}}
 verify_canvas(&mut m,text)?;
 m.prefs.control_center_theme="Original".into();m.page=Page::Settings;m.settings_tab=3;m.scroll=0.;m.layout_editor=None;m.toast=None;
 for dark in [false,true]{m.prefs.dark=dark;for(w,h)in [(900.,680.),(1200.,800.)]{let v=views::render(&m,text,w,h,&ViewState::default());if v.hits.iter().any(|h|matches!(h.action,Action::Import)){return Err("removed migration card is still reachable".into())}let name=format!("about-{w:.0}-{dark}.png");gpu.capture(&v.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}}
 m.page=Page::Home;m.settings_tab=255;m.prefs.dark=false;
 let frames=out.join("signature");std::fs::create_dir_all(&frames).map_err(|e|e.to_string())?;
 for frame in 0..49{let age=frame as f64/30.;let v=views::render(&m,text,900.,680.,&ViewState{signature_age:if age<dotisle_render::brand_signature::duration(false){Some(age)}else{None},..Default::default()});if frame<44&&v.hits.iter().any(|h|h.rect.y0>=views::TITLEBAR_H){return Err("signature exposed covered controls".into())}gpu.capture(&v.scene,900,680,&frames.join(format!("{frame:03}.png")))?;}
 m.dispatch(Action::IslandSettings(2));if m.page!=Page::Settings||m.settings_tab!=130{return Err("island preferences did not merge into settings".into())}
 Ok(captures)
}
fn h64(size:Size)->f64{size.dimensions().1}

fn verify_canvas(m:&mut Model,text:&mut Text)->Result<(),String>{
 m.dispatch(Action::LayoutOpen);m.dispatch(Action::LayoutTab(0));let font=m.setting("FontSize").as_f64().unwrap_or(14.);let e=m.layout_editor.as_mut().unwrap();let original=e.draft.clone();let r=lyric_core::custom_layout::elements(&e.draft.geometry(400.,1.,font)).into_iter().find(|(id,_)|*id==1).ok_or("title missing")?.1;
 e.begin_drag(Some(1));e.drag_to(1,[20.,40.,1.],(20.+r.x+5.,40.+r.y+5.),false,font);e.drag_to(1,[20.,40.,1.],(20.+r.x+21.,40.+r.y+29.),false,font);e.end_drag(false);let moved=e.draft.clone();if moved==original||!moved.enabled{return Err("canvas drag did not save a placement".into())}
 m.dispatch(Action::LayoutUndo);if m.layout_editor.as_ref().unwrap().draft!=original{return Err("canvas undo did not restore layout".into())}m.dispatch(Action::LayoutRedo);if m.layout_editor.as_ref().unwrap().draft!=moved{return Err("canvas redo lost placement".into())}
 let e=m.layout_editor.as_mut().unwrap();e.begin_drag(Some(1));e.drag_to(1,[0.,0.,1.],(r.x,r.y),false,font);e.drag_to(1,[0.,0.,1.],(r.x+72.,r.y+72.),false,font);e.end_drag(true);if e.draft!=moved{return Err("cancelled canvas drag was applied".into())}
 let e=m.layout_editor.as_mut().unwrap();let r=lyric_core::custom_layout::elements(&e.draft.geometry(400.,1.,font)).into_iter().find(|(id,_)|*id==6).ok_or("progress missing")?.1;e.begin_drag(Some(6));e.drag_to(6,[0.,0.,1.],(r.x+r.w-48.,r.y),true,font);e.end_drag(false);let g=e.draft.geometry(400.,1.,font);if g.track.w>=r.w{return Err("canvas resize did not change progress width".into())}if (g.track.x-g.progress_hit.x).abs()>8.||g.seek_chip.x<g.track.x-40.{return Err("progress resize separated its seek geometry".into())}
 m.dispatch(Action::LayoutNudge(1,0));m.dispatch(Action::LayoutApply);let stored=lyric_core::custom_layout::Layout::from_value(&m.setting("MusicCustomLayout"))?;if stored.elements.len()<2{return Err("canvas apply omitted placements".into())}
 for tab in 0..3{m.dispatch(Action::LayoutTab(tab));for(w,h)in [(900.,680.),(1200.,800.)]{m.scroll=0.;let v=views::render(m,text,w,h,&ViewState::default());m.scroll=v.max_scroll;let v=views::render(m,text,w,h,&ViewState::default());for t in 0..3{if !v.hits.iter().any(|h|matches!(h.action,Action::LayoutTab(n) if n==t)){return Err("fixed theme tab disappeared when inspector scrolled".into())}}}}
 Ok(())
}
